def report_before(marks):
    passed = 0
    for m in marks:
        if m >= 50:
            passed += 1
    lines = []
    for m in marks:
        if m >= 50:
            lines.append(str(m) + " P")
        else:
            lines.append(str(m) + " F")
    lines.append("passed: " + str(passed))
    return "\n".join(lines)


# After: the pass rule has one home; each function has one job
PASS_MARK = 50


def passes(mark):
    return mark >= PASS_MARK


def label(mark):
    return str(mark) + (" P" if passes(mark) else " F")


def report_after(marks):
    lines = [label(m) for m in marks]
    lines.append("passed: " + str(sum(passes(m) for m in marks)))
    return "\n".join(lines)


marks = [49, 50, 85]
print(report_after(marks))
print(report_before(marks) == report_after(marks))

